CREATE TABLE city (
    id BIGSERIAL PRIMARY KEY,
    country_code CHAR(2) NOT NULL,
    name VARCHAR(200) NOT NULL,
    ascii_name VARCHAR(200) NOT NULL,
    population INTEGER,
    UNIQUE (country_code, ascii_name)
);
CREATE INDEX city_country_search_idx ON city (country_code, ascii_name);

